{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "properties": {
    "summary": {
      "type": "string",
      "minLength": 20
    },
    "filesChanged": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
